/**
 * @suppress
 */
public object FfiConverterTypeSketchSession: FfiConverter<SketchSession, Pointer> {

    override fun lower(value: SketchSession): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): SketchSession {
        return SketchSession(value)
    }

    override fun read(buf: ByteBuffer): SketchSession {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: SketchSession) = 8UL

    override fun write(value: SketchSession, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



