/**
 * One drawing instruction. `transform` maps the op's coordinates into the background's space.
 */
sealed class DrawOp {
    
    data class FillPath(
        val `path`: PathData, 
        val `paint`: Paint, 
        val `rule`: FillRule, 
        val `opacity`: kotlin.Float, 
        val `transform`: Affine) : DrawOp() {
        companion object
    }
    
    data class StrokePath(
        val `path`: PathData, 
        val `paint`: Paint, 
        val `params`: StrokeParams, 
        val `opacity`: kotlin.Float, 
        val `transform`: Affine) : DrawOp() {
        companion object
    }
    
    data class PushClip(
        val `path`: PathData, 
        val `rule`: FillRule, 
        val `transform`: Affine) : DrawOp() {
        companion object
    }
    
    object PopClip : DrawOp()
    
    
    data class PushLayer(
        val `opacity`: kotlin.Float) : DrawOp() {
        companion object
    }
    
    object PopLayer : DrawOp()
    
    
    /**
     * Encoded image bytes drawn into the rect `x, y, width, height`.
     */
    data class Image(
        val `data`: kotlin.ByteArray, 
        val `format`: ImageFormat, 
        val `x`: kotlin.Float, 
        val `y`: kotlin.Float, 
        val `width`: kotlin.Float, 
        val `height`: kotlin.Float, 
        val `transform`: Affine) : DrawOp() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDrawOp : FfiConverterRustBuffer<DrawOp>{
    override fun read(buf: ByteBuffer): DrawOp {
        return when(buf.getInt()) {
            1 -> DrawOp.FillPath(
                FfiConverterTypePathData.read(buf),
                FfiConverterTypePaint.read(buf),
                FfiConverterTypeFillRule.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            2 -> DrawOp.StrokePath(
                FfiConverterTypePathData.read(buf),
                FfiConverterTypePaint.read(buf),
                FfiConverterTypeStrokeParams.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            3 -> DrawOp.PushClip(
                FfiConverterTypePathData.read(buf),
                FfiConverterTypeFillRule.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            4 -> DrawOp.PopClip
            5 -> DrawOp.PushLayer(
                FfiConverterFloat.read(buf),
                )
            6 -> DrawOp.PopLayer
            7 -> DrawOp.Image(
                FfiConverterByteArray.read(buf),
                FfiConverterTypeImageFormat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DrawOp) = when(value) {
        is DrawOp.FillPath -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePathData.allocationSize(value.`path`)
                + FfiConverterTypePaint.allocationSize(value.`paint`)
                + FfiConverterTypeFillRule.allocationSize(value.`rule`)
                + FfiConverterFloat.allocationSize(value.`opacity`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
        is DrawOp.StrokePath -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePathData.allocationSize(value.`path`)
                + FfiConverterTypePaint.allocationSize(value.`paint`)
                + FfiConverterTypeStrokeParams.allocationSize(value.`params`)
                + FfiConverterFloat.allocationSize(value.`opacity`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
        is DrawOp.PushClip -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePathData.allocationSize(value.`path`)
                + FfiConverterTypeFillRule.allocationSize(value.`rule`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
        is DrawOp.PopClip -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DrawOp.PushLayer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterFloat.allocationSize(value.`opacity`)
            )
        }
        is DrawOp.PopLayer -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DrawOp.Image -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`data`)
                + FfiConverterTypeImageFormat.allocationSize(value.`format`)
                + FfiConverterFloat.allocationSize(value.`x`)
                + FfiConverterFloat.allocationSize(value.`y`)
                + FfiConverterFloat.allocationSize(value.`width`)
                + FfiConverterFloat.allocationSize(value.`height`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
    }

    override fun write(value: DrawOp, buf: ByteBuffer) {
        when(value) {
            is DrawOp.FillPath -> {
                buf.putInt(1)
                FfiConverterTypePathData.write(value.`path`, buf)
                FfiConverterTypePaint.write(value.`paint`, buf)
                FfiConverterTypeFillRule.write(value.`rule`, buf)
                FfiConverterFloat.write(value.`opacity`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
            is DrawOp.StrokePath -> {
                buf.putInt(2)
                FfiConverterTypePathData.write(value.`path`, buf)
                FfiConverterTypePaint.write(value.`paint`, buf)
                FfiConverterTypeStrokeParams.write(value.`params`, buf)
                FfiConverterFloat.write(value.`opacity`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
            is DrawOp.PushClip -> {
                buf.putInt(3)
                FfiConverterTypePathData.write(value.`path`, buf)
                FfiConverterTypeFillRule.write(value.`rule`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
            is DrawOp.PopClip -> {
                buf.putInt(4)
                Unit
            }
            is DrawOp.PushLayer -> {
                buf.putInt(5)
                FfiConverterFloat.write(value.`opacity`, buf)
                Unit
            }
            is DrawOp.PopLayer -> {
                buf.putInt(6)
                Unit
            }
            is DrawOp.Image -> {
                buf.putInt(7)
                FfiConverterByteArray.write(value.`data`, buf)
                FfiConverterTypeImageFormat.write(value.`format`, buf)
                FfiConverterFloat.write(value.`x`, buf)
                FfiConverterFloat.write(value.`y`, buf)
                FfiConverterFloat.write(value.`width`, buf)
                FfiConverterFloat.write(value.`height`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






