/**
 * Gradient coordinates are in the op's local space, mapped by `transform` first.
 */
sealed class Paint {
    
    data class Solid(
        val v1: Color) : Paint() {
        companion object
    }
    
    data class LinearGradient(
        val `x1`: kotlin.Float, 
        val `y1`: kotlin.Float, 
        val `x2`: kotlin.Float, 
        val `y2`: kotlin.Float, 
        val `stops`: List<GradientStop>, 
        val `spread`: Spread, 
        val `transform`: Affine) : Paint() {
        companion object
    }
    
    data class RadialGradient(
        val `cx`: kotlin.Float, 
        val `cy`: kotlin.Float, 
        val `r`: kotlin.Float, 
        val `fx`: kotlin.Float, 
        val `fy`: kotlin.Float, 
        val `stops`: List<GradientStop>, 
        val `spread`: Spread, 
        val `transform`: Affine) : Paint() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypePaint : FfiConverterRustBuffer<Paint>{
    override fun read(buf: ByteBuffer): Paint {
        return when(buf.getInt()) {
            1 -> Paint.Solid(
                FfiConverterTypeColor.read(buf),
                )
            2 -> Paint.LinearGradient(
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterSequenceTypeGradientStop.read(buf),
                FfiConverterTypeSpread.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            3 -> Paint.RadialGradient(
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterFloat.read(buf),
                FfiConverterSequenceTypeGradientStop.read(buf),
                FfiConverterTypeSpread.read(buf),
                FfiConverterTypeAffine.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Paint) = when(value) {
        is Paint.Solid -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeColor.allocationSize(value.v1)
            )
        }
        is Paint.LinearGradient -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterFloat.allocationSize(value.`x1`)
                + FfiConverterFloat.allocationSize(value.`y1`)
                + FfiConverterFloat.allocationSize(value.`x2`)
                + FfiConverterFloat.allocationSize(value.`y2`)
                + FfiConverterSequenceTypeGradientStop.allocationSize(value.`stops`)
                + FfiConverterTypeSpread.allocationSize(value.`spread`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
        is Paint.RadialGradient -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterFloat.allocationSize(value.`cx`)
                + FfiConverterFloat.allocationSize(value.`cy`)
                + FfiConverterFloat.allocationSize(value.`r`)
                + FfiConverterFloat.allocationSize(value.`fx`)
                + FfiConverterFloat.allocationSize(value.`fy`)
                + FfiConverterSequenceTypeGradientStop.allocationSize(value.`stops`)
                + FfiConverterTypeSpread.allocationSize(value.`spread`)
                + FfiConverterTypeAffine.allocationSize(value.`transform`)
            )
        }
    }

    override fun write(value: Paint, buf: ByteBuffer) {
        when(value) {
            is Paint.Solid -> {
                buf.putInt(1)
                FfiConverterTypeColor.write(value.v1, buf)
                Unit
            }
            is Paint.LinearGradient -> {
                buf.putInt(2)
                FfiConverterFloat.write(value.`x1`, buf)
                FfiConverterFloat.write(value.`y1`, buf)
                FfiConverterFloat.write(value.`x2`, buf)
                FfiConverterFloat.write(value.`y2`, buf)
                FfiConverterSequenceTypeGradientStop.write(value.`stops`, buf)
                FfiConverterTypeSpread.write(value.`spread`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
            is Paint.RadialGradient -> {
                buf.putInt(3)
                FfiConverterFloat.write(value.`cx`, buf)
                FfiConverterFloat.write(value.`cy`, buf)
                FfiConverterFloat.write(value.`r`, buf)
                FfiConverterFloat.write(value.`fx`, buf)
                FfiConverterFloat.write(value.`fy`, buf)
                FfiConverterSequenceTypeGradientStop.write(value.`stops`, buf)
                FfiConverterTypeSpread.write(value.`spread`, buf)
                FfiConverterTypeAffine.write(value.`transform`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






